Definition wmatch_chk (seg : expr) (cells : list kentry) (litb : list (Z * Z)) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S10!2+?+0+0$seg;R+eC$cells;R!1+V+aP$litb;R!1+V0!3'f=0$kl;R0-^QRN$x;R!1+^Q+_:+^B!3'eD#4#3!3'K+0+0#12$v;R+_:!2'eK!2'eE#4!3,eF!1,aU#1,N!1,7|77f;!5'aR#1#4,N}bO$b;R+0!2'c9#1!3'L+0+0#3,bO#1").
Definition wmiss_chk (seg : expr) (cells : list kentry) (litb : list (Z * Z)) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S10!2+?+0+0$seg;R+eC$cells;R!1+V+aP$litb;R!1+V0!3'f>0$kl;R0-^QRN$x;R!1+^Q+_:+^B!3'eD#4#3!3'K+0+0#12$v;R+_:!2'eK!2'eE#4!3,eF!1,aU#1,N!1,7|77f;!5'aR#1#4,N}bO$b;R+0!1'aX!2'c9#1!3'L+0+0#3,bO#1").
Lemma wmatch_sound : forall seg cells litb E' (M' : mem) p w, wmatch_chk seg cells litb = true -> know_ok RSEGS E' M' cells -> PB.uv E' seg = p ->
