Lemma end_container_err_code : forall (arr : bool) c (M : mem) P ps w, PMR.rm_match c M P ps ->
  (ps_level ps = 0 -> PMW.r_code (PMW.rm_step PMR.the_rm (if arr then PMW.FEndArray else PMW.FEndObject) c w) = EC_CLEVEL arr) /\
